// ═══════════════════════════════════════════════════════════════════════════
// SECTION 3: Hydration (no console errors)
// ═══════════════════════════════════════════════════════════════════════════

test.describe('Hydration — all blocks', () => {

  test('home page loads without console errors', async ({ page }) => {
    const errors: string[] = []
    page.on('pageerror', err => errors.push(err.message))
    page.on('console', msg => {
      if (msg.type() === 'error') errors.push(msg.text())
    })
    await page.goto('/')
    await page.waitForTimeout(2000)
    const criticalErrors = errors.filter(e =>
      !e.includes('favicon') &&
      !e.includes('Failed to load resource') &&
      !e.includes('404')
    )
    expect(criticalErrors).toEqual([])
  })

  test('contact page loads without console errors', async ({ page }) => {
    const errors: string[] = []
    page.on('pageerror', err => errors.push(err.message))
    await page.goto('/contact')
    await page.waitForTimeout(2000)
    const title = await page.title()
    expect(title).not.toContain('500')
    expect(errors.filter(e => !e.includes('favicon'))).toEqual([])
  })

  test('messages page loads without console errors', async ({ page }) => {
    const errors: string[] = []
    page.on('pageerror', err => errors.push(err.message))
    await page.goto('/messages')
    await page.waitForTimeout(2000)
    expect(errors.filter(e => !e.includes('favicon'))).toEqual([])
  })

  test('all pages load without 500 errors', async ({ page }) => {
    const pages = ['/', '/contact', '/messages', '/event-list', '/agenda']
    for (const path of pages) {
      const errors: string[] = []
      page.on('pageerror', err => errors.push(err.message))
      await page.goto(path)
      await page.waitForTimeout(2000)
      const title = await page.title()
      expect(title, `${path}: 500 error`).not.toContain('500')
      expect(errors, `${path}: page errors`).toEqual([])
    }
  })
})

