// ═══════════════════════════════════════════════════════════════════════════
// SECTION 6: Cross-block integration
// ═══════════════════════════════════════════════════════════════════════════

test.describe('Cross-block integration', () => {

  test('all 15 block types are registered', () => {
    const registeredTypes = Object.keys(BLOCK_TYPES)
    expect(registeredTypes.length).toBe(15)
  })

  test('blocks span at least 2 categories', () => {
    const categories = new Set(Object.values(BLOCK_TYPES).map(d => d.category))
    expect(categories.size).toBeGreaterThanOrEqual(2)
  })

  test('blocks span at least 2 animation strategies', () => {
    const strategies = new Set(Object.values(BLOCK_TYPES).map(d => d.animations))
    expect(strategies.size).toBeGreaterThanOrEqual(2)
  })

  test('at least one block uses array type', () => {
    const hasArray = Object.entries(BLOCK_TYPES).some(([_, def]) =>
      def.schema.some((f: any) => f.type === 'array')
    )
    expect(hasArray).toBe(true)
  })

  test('at least one block uses each major field type', () => {
    const usedTypes = new Set<string>()
    for (const def of Object.values(BLOCK_TYPES)) {
      for (const field of def.schema) {
        usedTypes.add(field.type)
      }
    }
    expect(usedTypes.has('text')).toBe(true)
    expect(usedTypes.has('animation')).toBe(true)
    expect(usedTypes.has('color')).toBe(true)
  })
})
